# -*- coding: utf-8 -*-
"""定爵第三 — 日本語訳。"""

TITLE = '第三篇　定爵（ていしゃく）'
HEAD = '''十五段。全書で最も読みにくく、最も「文章」らしくない一篇である。ほとんど文が無く、あるのは名目ばかりだ。「天に順い、財を阜（ゆた）かにし、衆を懌（よろこ）ばせ、地を利し、兵を右（たっと）ぶ、これを五慮という」。「服せず、信ぜず、和せず、怠り、疑い、厭き、懾（おそ）れ、枝柱（そご）し、詘（くっ）し、頓（つか）れ、肆（ほしいまま）にし、崩れ、緩む、これを戦患という」。まず名を立て、次に界説を下す条文の連続で、先秦の兵書のなかで「用語集」に最も近い文字である。読みにくいのもそのためで、明以来の注家は誰もこの篇に脱簡・錯簡があることを認めており、通じないところでは諸説を並べるほかない。本頁もそういう箇所を強いて解かず、字も改めない。二つだけ覚えておく値打ちがある。「将は身なり、卒は支（てあし）なり、伍は指拇（ゆびとつまさき）なり」——軍隊を一つの身体と見る比喩。そして「厲祥を滅する道」の後半、「その溢るるを成し、その好むところを奪い、我は外より、内よりせしむ」——十字で陰謀を書き尽くしている。篇名「定爵」は冒頭二字を取ったもので、本書の篇名はみなこの式である。'''

PARA = {
 'p3-1': 'およそ戦は、爵位を定め、功罪を著（あら）わし、遊士を収め、教詔を申（の）べ、厥（そ）の衆に訊（と）い、厥の技を求め、慮りを方（くら）べて物を極め、嫌（うたがわ）しきを変（わか）ち疑わしきを推し、力を養い巧を索（もと）め、心の動くに因る。（「著」は明らかにすること。「方慮極物」の「方」は比べはかること。「変嫌推疑」は疑わしいものを分かち、怪しいものを推しはかること。十句すべて開戦前の事で、交刃を言う句は一つもない。この篇は終始そうである。）',
 'p3-2': 'およそ戦は、衆を固め、利を相（み）、乱を治め、進止を制し、正に服させ、恥を成さしめ、法を約（つづ）め、罰を省く。小罪も乃ち殺す。小罪に勝てば、大罪は因（したが）って止む。（「相利」の「相」は見ること。「罰を省く」と「小罪も殺す」は矛盾するようで矛盾しない——罰は少なく、少ない罰は必ず行う、ということである。）',
 'p3-3': '天に順い、財を阜かにし、衆を懌ばせ、地を利し、兵を右ぶ。これを五慮という。天に順うとは時を奉ずること、財を阜かにするとは敵に因ること、衆を懌ばすとは勉めて若（したが）わせること、地を利すとは隘・険阻を守ること、兵を右ぶとは弓矢は以て禦ぎ、殳矛は以て守り、戈戟は以て助けること。およそ五兵は五つながらその当たるところがあり、長は以て短を衛り、短は以て長を救う。迭（かわ）るがわる戦えば久しく、みな戦えば強い。物を見てこれと侔（ひと）しくする、これを両（りょう）にするという。（「阜」は厚くする、「懌」は悦ばせる、「右」は尚ぶ。「殳」は竹木の長柄の武器。「侔」は等しくすること。）',
 'p3-4': '主は固く勉めて若わせ、敵を視てのち挙がる。将の心も心であり、衆の心も心である。馬牛車兵の佚（やす）み飽きたるは力である。教えは豫（あらかじ）めにあり、戦は節にある。将は身であり、卒は支（てあし）であり、伍は指拇である。（「佚」は逸。「豫」は予。末の三句は全書で最もよい比喩である——軍隊は一つの身体であり、将はその身体の主人ではなく、身体そのものである。）',
 'p3-5': 'およそ戦は智であり、鬬（とう、切りむすぶこと）は勇であり、陳（じん、陣立て）は巧である。おのれの欲するところを用い、おのれの能くするところを行い、欲せざるところ能わざるところを廃する。敵に対しては、これと反対にする。（四庫本は「凡戦智也」を「凡戦権也」に作る。「敵に於いては是に反す」——敵には、その欲せぬものを用いさせ、その能わぬことをさせる。一句で前文をそっくり裏返す、篇中最も機鋒のある一句である。）',
 'p3-6': 'およそ戦には天あり、財あり、善あり。時日を遷さず、亀（うらない）に勝を得て微（ひそ）かに行う、これを天ありという。衆に蓄えあり、因るところあって美を生ずる、これを財ありという。人は陳に習い器は利く、物を極めて豫（あらかじ）め備える、これを善ありという。人が勉めて任に及ぶ、これを楽人（らくじん）という。大軍は固きを以てし、多力は煩（こま）やかなるを以てし、物に堪えて治め簡（やす）く、物を見て卒（にわか）に応ずる、これを行豫という。軽車・軽徒、弓矢固く禦ぐ、これを大軍という。密、静、内に力多き、これを固陳という。これに因って進退する、これを多力という。上に暇あって人を教える、これを煩陳という。然（しか）く職あり、これを堪物という。これに因って物を弁ずる、これを簡治という。（「亀勝」は卜占に吉兆を得ること、「微行」は隠れて動くこと。「煩」は細やかの意で、わずらわしいの意ではない。まず六つの名目を立て、次にそれを逆から一つずつ定義する。「甲乙丙、是を某という」と「某、甲乙丙」が交錯する構文で、先秦の文章には珍しい体である。四庫本は「因是辨物」を「因是堪物」に作る。）',
 'p3-7': '衆を称（はか）り、地に因り、敵に因り、陳を令する。攻・戦・守・進・退・止、前後に序あり、車と徒と相因る、これを戦参という。服せず、信ぜず、和せず、怠り、疑い、厭き、懾れ、枝柱し、詘し、頓れ、肆にし、崩れ、緩む、これを戦患という。驕驕、懾懾、吟曠（うめき、なまける）、虞懼、事ごとに悔ゆ、これを毀折という。大小、堅柔、参伍、衆寡、およそ両（ふた）つなるもの、これを戦権という。（「枝柱」は互いに食い違うこと。影宋鈔本は「校拄」に作る。「吟曠」を二本はともに「吟嚝」に作る。「是為戦参」を二本はともに「是謂戦参」に作り、下の三つの「是謂」と揃うが、底本のままとした。四庫本は「詘頓」を「詘煩」に作る。十三字が軍隊のかかる病をすべて数え尽くしている。先秦の兵書で最も長い病名の一覧である。）',
 'p3-8': 'およそ戦は、遠きは間（かん、間諜）し、近きは観る。時に因り、財に因り、信を貴び、疑を悪む。兵を作（おこ）すは義に、事を作すは時に、人を使うは恵を以てする。敵を見ては静かに、乱を見ては暇（ゆる）やかに、危難を見てはその衆を忘れない。国に居ては恵にして信、軍に在っては広くして武、刃上（じんじょう、刃を交える際）には果にして敏。国に居ては和、軍に在っては法、刃上には察。国に居ては好を見（しめ）し、軍に在っては方を見し、刃上には信を見す。（「間遠」は遠方に間諜を放つこと。「刃上」は刃を交えるとき。三組それぞれ三句、国に居るとき・軍に在るとき・刃上のとき——同じ人が三つの場で三つの姿になり、しかも三つとも信を失わない。）',
 'p3-9': 'およそ陳は、行（こう、行軍）には疏（あら）く、戦には密に、兵は雑（まじ）える。人の教え厚ければ、静にして乃ち治まり、威と利とが章（あき）らかになる。相守ること義なれば人は勉め、慮り多く成れば人は服する。時に中（あた）って服すれば、その次（ついで）は治まる。物すでに章らかなれば目は乃ち明らかになり、慮りすでに定まれば心は乃ち強くなる。進退に疑いなく、敵を見ては謀（はか）り直さない。誅を聴（ゆる）すときは、その名を誰（と）わず、その旗を変えない。（「兵を雑える」は『天子之義』の「兵、雑らざれば利あらず」を承ける。四庫本は「無誰其名」を「無誑其名」に作る。末の三句は最も冷たい——軍法の行われるところ、名は問わず、旗は動かさない。動かせば軍心が疑う。）',
 'p3-10': 'およそ事は、善ければ長く、古に因れば行われる。誓いが章らかに作られれば人は乃ち強くなり、厲祥（れいしょう、凶のきざし）は滅する。厲を滅する道に二つある。一に義という——これを被（おお）うに信を以てし、これに臨むに強を以てし、基を成し、天下の形を一にすれば、人として悦ばざるはない。これをその人を兼ね用いるという。二に権という——その溢るるを成し、その好むところを奪い、我は外より、内よりせしめる。（「厲祥」は凶悪のきざし。「その溢るるを成す」は満ち溢れさせて後に傾けること。末の十字は陰謀を書き尽くしているが、上の「その人を兼ね用いる」がちょうどその対になる。義と権、この書は両方を出している。）',
 'p3-11': '一に人といい、二に正といい、三に辞といい、四に巧といい、五に火といい、六に水といい、七に兵という。これを七政という。栄・利・恥・死、これを四守という。容色に威を積むも、意を改めさせるにすぎない。おおよそこの道である。ただ仁のみ親しみがある。仁ありて信なければ、かえってその身を敗る。人は人、正は正、辞は辞、火は火。（「四守」は人心を守るに足る四つのもの。末の四つの畳語は古来解しがたい。一説にそれぞれ本来のままに用いることとし、一説に「人人」は「任人」の誤りとする。本頁は字を改めず、強いて解きもしない——この篇に脱簡・錯簡のあることは旧注のいずれも認めており、通じない箇所は諸説を並べておけばよい。）',
 'p3-12': 'およそ戦の道は、すでにその気を作（おこ）したうえで、これに因ってその政を発し、これに仮（か）すに色を以てし、これを道（みちび）くに辞を以てし、懼れに因って戒め、欲に因って事とし、敵を蹈（ふ）んで地を制し、職を以てこれに命ずる。これを戦法という。（「これに仮すに色を以てす」は顔色を見せてやること。「敵を蹈んで地を制す」は敵地に入ってその地の利を取ること。）',
 'p3-13': 'およそ人の形は、衆の求めに由る。試みるに名行を以てし、必ずこれを善く行う。もし行うべくして行われなければ、身を以てこれを将（ひき）い、もし行って行われれば、因ってこれを使い忘れさせない。三たびにして乃ち章（きまり）と成る。人の生の宜しきを法という。（四庫本は「凡人之形」を「凡人之行」に作る。「三乃成章」は三度にして定則となること。末の一句が篇中で最もよい——法は外から加えられるものではなく、人がどう生きるべきかである。）',
 'p3-14': 'およそ乱を治める道に七つある。一に仁、二に信、三に直、四に一、五に義、六に変、七に尊。法を立てるに七つある。一に受（命を受ける）、二に灋（法度）、三に立、四に疾、五にその服を御（さだ）める、六にその色を等（わ）ける、七に百官は宜しく淫服（分を越えた服）なかるべし。およそ軍は、灋を己に在らしめるを専といい、下とともに法を畏れるを法という。軍に小聴なく、戦に小利なし。日に成り行（おこな）い微（こま）やかなるを道という。（「淫服」は等級を越えた服色。「宜」の字を底本は脱し、二本はともに有する。今これを補った——本頁が補った唯一の字である。「灋を己に在らしめるを専といい、下とともに法を畏れるを法という」の一句のうちに「灋」「法」の両形が並び用いられ、二旧本も同じである。訛字ではないので統一しない。四庫本は「七曰尊」を「七曰専」に作る。）',
 'p3-15': 'およそ戦は、正、行われざれば則ち事は専にし、服さざれば則ち法により、相信ぜざれば則ち一にする。もし怠れば則ちこれを動かし、もし疑えば則ちこれを変じ、もし人、上を信ぜざれば則ちその復（かえ）らざるを行う。古よりの政である。（影宋鈔本は「正不行」を「正不符」に作る。「その復らざるを行う」は旧注が一定せず、一説に「すでに下した令を翻さず行う」とする。この篇は最後まで条文の連なりで、一つの物語も一つの人名も出てこない。）',
}
